CREATE TABLE IF NOT EXISTS digital_transactions(id CHAR(36) PRIMARY KEY,correlation_id CHAR(36) NOT NULL,customer_id CHAR(36) NOT NULL,idempotency_key VARCHAR(100) NOT NULL,transaction_type ENUM('OWN_ACCOUNT','INTERNAL') NOT NULL,source_account_id VARCHAR(100) NOT NULL,destination_account_id VARCHAR(100) NULL,destination_account_number_masked VARCHAR(30) NOT NULL,amount_minor BIGINT UNSIGNED NOT NULL,currency CHAR(3) NOT NULL,reference VARCHAR(140) NOT NULL,status ENUM('CREATED','PENDING','PROCESSING','SUCCESS','FAILED','REVERSED','UNKNOWN') NOT NULL,provider_reference VARCHAR(180) NULL,failure_code VARCHAR(80) NULL,failure_message VARCHAR(255) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),completed_at DATETIME(3) NULL,UNIQUE KEY uq_digital_transfer_idempotency(customer_id,idempotency_key),UNIQUE KEY uq_digital_transfer_correlation(correlation_id),INDEX idx_digital_transfer_customer_time(customer_id,created_at),FOREIGN KEY(customer_id) REFERENCES users(id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS transfer_step_up_authorizations(id CHAR(36) PRIMARY KEY,customer_id CHAR(36) NOT NULL,otp_challenge_id CHAR(36) NOT NULL,intent_hash CHAR(64) NOT NULL,expires_at DATETIME(3) NOT NULL,consumed_at DATETIME(3) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(customer_id) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(otp_challenge_id) REFERENCES otp_challenges(id) ON DELETE RESTRICT,INDEX idx_transfer_stepup(customer_id,expires_at));
CREATE TABLE IF NOT EXISTS customer_notifications(id CHAR(36) PRIMARY KEY,customer_id CHAR(36) NOT NULL,event_type VARCHAR(100) NOT NULL,title VARCHAR(160) NOT NULL,message VARCHAR(500) NOT NULL,entity_type VARCHAR(80) NULL,entity_id VARCHAR(100) NULL,status ENUM('PENDING','DELIVERED','FAILED','READ') NOT NULL DEFAULT 'DELIVERED',created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),read_at DATETIME(3) NULL,INDEX idx_notification_customer_time(customer_id,created_at),FOREIGN KEY(customer_id) REFERENCES users(id) ON DELETE RESTRICT);
INSERT IGNORE INTO schema_migrations(version) VALUES('012_secure_transfers');
